"269 :     private BigFraction(final double value, final double epsilon,
270 :                         final int maxDenominator, int maxIterations)
271 :         throws FractionConversionException {
272 :         long overflow = Integer.MAX_VALUE;
273 :         double r0 = value;
274 :         long a0 = (long) FastMath.floor(r0);
275 :         if (a0 > overflow) {
276 :             throw new FractionConversionException(value, a0, 1l);
277 :         }
278 : 
279 :         // check for (almost) integer arguments, which should not go
280 :         // to iterations.
281 :         if (FastMath.abs(a0 - value) < epsilon) {
282 :             numerator = BigInteger.valueOf(a0);
283 :             denominator = BigInteger.ONE;
284 :             return;
285 :         }
286 : 
287 :         long p0 = 1;
288 :         long q0 = 0;
289 :         long p1 = a0;
290 :         long q1 = 1;
291 : 
292 :         long p2 = 0;
293 :         long q2 = 1;
294 : 
295 :         int n = 0;
296 :         boolean stop = false;
297 :         do {
298 :             ++n;
299 :             final double r1 = 1.0 / (r0 - a0);
300 :             final long a1 = (long) FastMath.floor(r1);
301 :             p2 = (a1 * p1) + p0;
302 :             q2 = (a1 * q1) + q0;
303 :             if ((p2 > overflow) || (q2 > overflow)) {
304 :                 // in maxDenominator mode, if the last fraction was very close to the actual value
305 :                 // q2 may overflow in the next iteration; in this case return the last one.
306 :                 throw new FractionConversionException(value, p2, q2);
307 :             }
308 : 
309 :             final double convergent = (double) p2 / (double) q2;
310 :             if ((n < maxIterations) &&
311 :                 (FastMath.abs(convergent - value) > epsilon) &&
312 :                 (q2 < maxDenominator)) {
313 :                 p0 = p1;
314 :                 p1 = p2;
315 :                 q0 = q1;
316 :                 q1 = q2;
317 :                 a0 = a1;
318 :                 r0 = r1;
319 :             } else {
320 :                 stop = true;
321 :             }
322 :         } while (!stop);
323 : 
324 :         if (n >= maxIterations) {
325 :             throw new FractionConversionException(value, maxIterations);
326 :         }
327 : 
328 :         if (q2 < maxDenominator) {
329 :             numerator   = BigInteger.valueOf(p2);
330 :             denominator = BigInteger.valueOf(q2);
331 :         } else {
332 :             numerator   = BigInteger.valueOf(p1);
333 :             denominator = BigInteger.valueOf(q1);
334 :         }
335 :     }"

